var i=[{title:`Tipuri frecvente de plimbări cu greutate`,text:`O plimbare a fermierului folosește câte o greutate în fiecare mână. O plimbare cu valiza folosește o greutate pe o singură parte, așa că trunchiul trebuie să reziste îndoirii în lateral. O plimbare cu greutatea în față ține sarcina aproape de piept, iar una cu greutatea deasupra capului cere mai mult de la stabilitatea umărului și are nevoie de mai mult spațiu pe verticală. Fiecare poziție schimbă mușchii și îndemânarea implicate.`},{title:`Tehnica de bază`,text:`Alege o sarcină pe care o poți ține în siguranță pe tot parcursul drumului, stai drept într-o postură comodă și mergi cu pași deliberați. Ține greutatea sigur, nu te apleca mult spre ea sau în partea opusă și continuă să respiri pe o distanță lungă. Încetinește când întorci și ține traseul liber.`},{title:`Cum dozezi plimbările cu greutate`,text:`Plimbările cu greutate se numără pe distanță sau timp, nu pe repetări. De exemplu, du două gantere pe care le poți ține stabil 20–30 de secunde, odihnește-te, apoi repetă. Când priza și postura rămân la fel, adaugă puțină distanță, timp sau greutate. O greutate mai mare nu ajută dacă îți face pașii grăbiți și neregulați.`},{title:`Spațiu și siguranță`,text:`Verifică dacă traseul tău are destul spațiu liber pe podea, o suprafață antiderapantă și nicio persoană sau vreun obiect în cale. Pune greutățile jos controlat și nu le lăsa să cadă. Sari peste plimbările cu greutatea deasupra capului sub un tavan jos sau când nu ești sigur de controlul umărului. Antrenează întotdeauna ambele părți la plimbările cu greutate pe o singură parte.`},{title:`Folosirea TrainUp`,text:`Plimbările cu greutate pot ocupa un loc în partea de forță când ai echipamentul și spațiul pentru a merge. Planul tău verifică suprafața podelei setată în Profil. Dacă spatele sau mâinile îți limitează câtă încărcare a coloanei sau câtă muncă de priză poți suporta, adaugă acea zonă a corpului ca limitare în Profil, ca planul să poată omite exercițiile care nu se potrivesc.`}];var t=[{label:`Biblioteca de exerciții ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`NSCA: bazele siguranței și ale antrenamentului de forță`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};